public class UrlBuilderTest {
    @Test
    public void testBuildUrl() {
        UrlBuilder urlBuilder = new UrlBuilder(new URL("https://example.com"));
        assertEquals(null, urlBuilder.build());
    }

    @Test
    public void testAppendKeyValue() throws UnsupportedEncodingException {
        UrlBuilder urlBuilder = new UrlBuilder(new URL("https://example.com"));
        urlBuilder.appendKeyVal(new java.util.HashMap<java.net.KeyedHash, String>() {{
            put("key", "value");
        }});
        assertEquals("https://example.com?key=value", urlBuilder.build().toString());
    }

    @Test
    public void testAppendKeyValue_ThrowsUnsupportedEncodingException() {
        UrlBuilder urlBuilder = new UrlBuilder(new URL("https://example.com"));
        String exception = null;
        try {
            urlBuilder.appendKeyVal(new java.util.HashMap<java.net.KeyedHash, String>() {{
                put("key", "value");
            }});
            throw new UnsupportedEncodingException(exception);
        } catch (UnsupportedEncodingException e) {
            assertEquals("UnsupportedEncodingException: ", e.getMessage());
        }
    }

    @Test
    public void testAppendKeyValue_KVMap() throws UnsupportedEncodingException {
        UrlBuilder urlBuilder = new UrlBuilder(new URL("https://example.com"));
        java.util.Map<java.net.KeyedHash, String> kvMap = new java.util.HashMap<java.net.KeyedHash, String>() {{
            put("key1", "value1");
            put("key2", "value2");
        }};
        urlBuilder.appendKeyVal(kvMap);
        assertEquals("https://example.com?key1=value1&key2=value2", urlBuilder.build().toString());
    }
}
